package service

import (
	"testing"
	"time"

	"lms/backend/internal/models"
)

// 第一轮：纯业务规则单元测试（无 I/O 依赖）。

func TestCheckBorrow(t *testing.T) {
	cases := []struct {
		name              string
		available, active, overdue int
		wantErr           bool
	}{
		{"全部满足", 3, 2, 0, false},
		{"无库存", 0, 0, 0, true},
		{"达到上限", 3, 5, 0, true},
		{"存在逾期", 3, 1, 1, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := checkBorrow(c.available, c.active, c.overdue)
			if (err != nil) != c.wantErr {
				t.Fatalf("期望错误=%v，实际=%v", c.wantErr, err)
			}
		})
	}
}

func TestCheckRenew(t *testing.T) {
	today := time.Now().Format(dateLayout)
	future := time.Now().AddDate(0, 0, 10).Format(dateLayout)
	past := time.Now().AddDate(0, 0, -2).Format(dateLayout)

	if err := checkRenew(0, future, today); err != nil {
		t.Fatalf("正常续借应通过，实际=%v", err)
	}
	if err := checkRenew(1, future, today); err == nil {
		t.Fatal("续借次数超限应拒绝")
	}
	if err := checkRenew(0, past, today); err == nil {
		t.Fatal("逾期图书续借应拒绝")
	}
}

func TestCheckTotalQty(t *testing.T) {
	if err := checkTotalQty(5, 3); err != nil {
		t.Fatalf("馆藏>=已借应通过，实际=%v", err)
	}
	if err := checkTotalQty(2, 3); err == nil {
		t.Fatal("馆藏小于已借应拒绝")
	}
}

func TestCalcFine(t *testing.T) {
	today := time.Now()
	due := today.AddDate(0, 0, -10).Format(dateLayout)
	ret := today.Format(dateLayout)
	fine := calcFine(due, ret)
	if fine != 10*FinePerDay {
		t.Fatalf("逾期10天罚款期望 %.1f，实际 %.1f", 10*FinePerDay, fine)
	}
	// 未逾期
	due2 := today.AddDate(0, 0, 5).Format(dateLayout)
	if f := calcFine(due2, ret); f != 0 {
		t.Fatalf("未逾期罚款应为0，实际 %.1f", f)
	}
}

func TestStateText(t *testing.T) {
	now := time.Now()
	// 已归还
	r := modelBorrow("returned", now.AddDate(0, 0, 5).Format(dateLayout))
	if got := stateText(r, now); got != "已归还" {
		t.Fatalf("已归还状态错误：%s", got)
	}
	// 逾期
	r2 := modelBorrow("borrowed", now.AddDate(0, 0, -7).Format(dateLayout))
	if got := stateText(r2, now); got != "已逾期 7 天" {
		t.Fatalf("逾期状态错误：%s", got)
	}
	// 借阅中
	r3 := modelBorrow("borrowed", now.AddDate(0, 0, 12).Format(dateLayout))
	if got := stateText(r3, now); got != "借阅中（剩 12 天）" {
		t.Fatalf("借阅中状态错误：%s", got)
	}
}

func modelBorrow(status, due string) models.BorrowRecord {
	return models.BorrowRecord{Status: status, DueDate: due}
}

package service

import (
	"errors"
	"fmt"
	"strings"

	"lms/backend/internal/models"

	"golang.org/x/crypto/bcrypt"
)

// ListReaders 管理员查询读者列表。
func (s *Service) ListReaders(keyword string) ([]models.ReaderWithUser, error) {
	return s.repo.ListReaders(strings.TrimSpace(keyword))
}

// AddReader 管理员新增读者，返回读者编号。
func (s *Service) AddReader(actor *models.User, username, password, realName, phone string) (string, error) {
	username = strings.TrimSpace(username)
	realName = strings.TrimSpace(realName)
	if len(username) < 3 {
		return "", Error("用户名至少 3 个字符")
	}
	if len(password) < 6 {
		return "", Error("初始口令至少 6 位")
	}
	if realName == "" {
		return "", Error("姓名不能为空")
	}
	if _, err := s.repo.GetUserByUsername(username); err == nil {
		return "", Error("用户名已存在")
	} else if !errors.Is(err, models.ErrNotFound) {
		return "", err
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	no, err := s.repo.CreateReaderAccount(username, string(hash), realName, strings.TrimSpace(phone))
	if err != nil {
		return "", Error("新增失败：用户名可能已存在")
	}
	_ = s.log(actor.ID, actor.Username, "新增读者", realName+"（"+no+"）")
	return no, nil
}

// SetReaderStatus 管理员启用/停用读者账号。
func (s *Service) SetReaderStatus(actor *models.User, userID int64, status string) error {
	if status != "active" && status != "disabled" {
		return Error("状态值非法")
	}
	u, err := s.repo.GetUserByID(userID)
	if err != nil {
		return Error("用户不存在")
	}
	if u.Role != "reader" {
		return Error("只能对读者账号执行此操作")
	}
	if err := s.repo.SetUserStatus(userID, status); err != nil {
		return err
	}
	label := "启用"
	if status == "disabled" {
		label = "停用"
	}
	return s.log(actor.ID, actor.Username, label+"读者", u.RealName)
}

// ResetReaderPassword 管理员重置读者口令，返回新临时口令。
func (s *Service) ResetReaderPassword(actor *models.User, userID int64) (string, error) {
	u, err := s.repo.GetUserByID(userID)
	if err != nil {
		return "", Error("用户不存在")
	}
	if u.Role != "reader" {
		return "", Error("只能重置读者口令")
	}
	tmp := fmt.Sprintf("reset%06d", userID)
	hash, err := bcrypt.GenerateFromPassword([]byte(tmp), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	if err := s.repo.ResetPassword(userID, string(hash)); err != nil {
		return "", err
	}
	_ = s.log(actor.ID, actor.Username, "重置口令", u.RealName)
	return tmp, nil
}

// ListCategories 查询全部分类。
func (s *Service) ListCategories() ([]models.Category, error) {
	return s.repo.ListCategories()
}

// AddCategory 新增分类。
func (s *Service) AddCategory(actor *models.User, name string) error {
	name = strings.TrimSpace(name)
	if name == "" {
		return Error("分类名称不能为空")
	}
	if err := s.repo.CreateCategory(name); err != nil {
		return Error("分类已存在")
	}
	return s.log(actor.ID, actor.Username, "新增分类", name)
}

// Package service 承载全部业务规则，只依赖自行定义的仓储端口（Repo），
// 不直接依赖 SQLite 或 HTTP，实现与具体技术的解耦。
package service

import (
	"lms/backend/internal/models"
)

// 业务常量
const (
	LoanDays    = 30   // 借期（天）
	MaxBorrow   = 5    // 每人最大在借数量
	MaxRenew    = 1    // 每本最大续借次数
	RenewDays   = 30   // 续借延长天数
	FinePerDay  = 0.5  // 逾期罚款（元/天）
)

// Error 业务规则错误，可直接向用户展示。
type Error string

func (e Error) Error() string { return string(e) }

// Repo 仓储端口：由存储层（SQLite 适配器）实现。
type Repo interface {
	// 用户 / 读者 / 分类
	GetUserByUsername(string) (*models.User, error)
	GetUserByID(int64) (*models.User, error)
	CreateReaderAccount(username, passwordHash, realName, phone string) (string, error)
	UpdatePassword(int64, string) error
	SetUserStatus(int64, string) error
	ResetPassword(int64, string) error
	ListReaders(string) ([]models.ReaderWithUser, error)
	GetReaderByUserID(int64) (*models.Reader, error)
	GetReaderByID(int64) (*models.Reader, error)
	ListCategories() ([]models.Category, error)
	CreateCategory(string) error
	// 图书
	ListBooks(string, *int64) ([]models.Book, error)
	GetBook(int64) (*models.Book, error)
	CreateBook(*models.Book) error
	UpdateBook(*models.Book) error
	DeleteBook(int64) error
	CountActiveBorrowsForBook(int64) (int, error)
	DecAvailable(int64) error
	IncAvailable(int64) error
	// 借阅
	CreateBorrow(*models.BorrowRecord) error
	GetBorrow(int64) (*models.BorrowRecord, error)
	ListActive(*int64) ([]models.BorrowRecord, error)
	ListHistory(*int64) ([]models.BorrowRecord, error)
	MarkReturned(int64, string, float64) error
	MarkRenewed(int64, string, int) error
	CountActive(int64) (int, error)
	CountOverdue(int64, string) (int, error)
	AddLog(userID *int64, username, action, detail, createdAt string) error
	// 统计
	Dashboard(string) (*models.Dashboard, error)
	CategoryStats() ([]models.CategoryStat, error)
	HotBooks(int) ([]models.HotBook, error)
	RecentLogs(int) ([]models.OperationLog, error)
}

// Service 业务服务入口。
type Service struct {
	repo Repo
}

// New 创建业务服务。
func New(repo Repo) *Service {
	return &Service{repo: repo}
}

